/** Actual whole original report and target body. Genesis and model responses are fictional. */
class ReportSupplementBaselineTest {
 boolean mysql(){return false;}
 ReportNativeGenerationIntegrationTest h;ReportSupplementBaselineService baseline;JdbcLatestReportIntent.Scope scope;String id;
 void setup()throws Exception{h=new ReportNativeGenerationIntegrationTest(){@Override boolean mysql(){return ReportSupplementBaselineTest.this.mysql();}};h.setup();var f=h.h.h.h.f.data.nativeData().fixture().f();var s=h.h.h.original.scope();scope=new JdbcLatestReportIntent.Scope(s.logicalKey(),s.stage().name().toLowerCase(java.util.Locale.ROOT),s.day());id=ReportPreparationService.contentId(s);baseline=new ReportSupplementBaselineService(f.source,f.tx,new JdbcLatestReportIntent(f.source),new ReportPreparedInputService(f.source,f.tx),new ReportSupplementContentBaselineService(f.source,f.tx));}
 ReportSupplementBaselineService.Captured capture(String content,Long revision){return baseline.capture(scope,0,content,revision);}
 void check(ReportSupplementBaselineService.Captured captured){var f=h.h.h.h.f.data.nativeData().fixture().f();f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-dual-baseline","fictional-dual-baseline",null),k->null,a->{baseline.requireCurrent(captured);return true;});}
 @Test void ActualOriginalIntentAndAbsentOrNativeBodyProduceImmutableNextScope()throws Exception{setup();var absent=capture(null,null);assertNull(absent.content().revision());assertEquals(h.h.h.original,absent.original());assertEquals(2,absent.nextScope().generation());check(absent);h.apply();assertThrows(RuntimeException.class,()->check(absent));assertThrows(RuntimeException.class,()->capture(null,null));var current=capture(id,1L);check(current);assertEquals(1L,current.content().revision());assertEquals(1L,current.content().bodyRevision());assertEquals(h.identity.rootId(),current.content().inputJobId());assertEquals(1,h.reportSends);assertTrue(current.toString().contains("redacted"));}
 @Test void LaterIntentOrMetadataRevisionCannotPassPreviouslyCapturedWriterBaseline()throws Exception{setup();h.apply();var current=capture(id,1L);var f=h.h.h.h.f.data.nativeData().fixture().f();f.jdbc.update("UPDATE contents SET revision=revision+1 WHERE id=?",id);assertThrows(RuntimeException.class,()->check(current));assertThrows(RuntimeException.class,()->capture(id,1L));check(capture(id,2L));setup();var old=capture(null,null);f=h.h.h.h.f.data.nativeData().fixture().f();final var data=f;String next=JdbcFrozenInputs.stableId("intent",scope.logicalKey()+":2");ReportOriginalCompletionTest.utc(()->data.writes.execute(new SharedWriteExecutor.ActionContext("fictional-later-intent",next,null),k->null,a->new JdbcJobRecords(data.source).ensureIntent(new JdbcJobRecords.Intent(next,scope.logicalKey(),2,scope.type(),scope.day()),h.clock.instant())));assertThrows(RuntimeException.class,()->check(old));assertThrows(RuntimeException.class,()->capture(null,null));}
 @Test void MissingWholeOriginalReceiptOrWrongExpectedIdentityRefuseRatherThanUseCurrentBody()throws Exception{setup();h.apply();assertThrows(RuntimeException.class,()->capture("fictional-alias",1L));assertThrows(RuntimeException.class,()->baseline.capture(scope,1,id,1L));var captured=capture(id,1L);var f=h.h.h.h.f.data.nativeData().fixture().f();f.jdbc.update("DELETE FROM jobs WHERE target_type='generation_prepare' AND operator_id=?",JdbcReportPreparedInputs.ACTOR);assertThrows(RuntimeException.class,()->check(captured));assertThrows(RuntimeException.class,()->capture(id,1L));assertEquals(1L,f.jdbc.queryForObject("SELECT COUNT(*) FROM contents WHERE kind='report'",Long.class));}
 @Test void IssuerOwnedTransactionsColdConstructionAndMalformedCommandsRefuse()throws Exception{setup();var captured=capture(null,null);assertThrows(RuntimeException.class,()->baseline.requireCurrent(captured));var f=h.h.h.h.f.data.nativeData().fixture().f();var other=new ReportSupplementBaselineService(f.source,f.tx,new JdbcLatestReportIntent(f.source),new ReportPreparedInputService(f.source,f.tx),new ReportSupplementContentBaselineService(f.source,f.tx));assertThrows(RuntimeException.class,()->f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-wrong-issuer","fictional-wrong-issuer",null),k->null,a->{other.requireCurrent(captured);return true;}));assertThrows(RuntimeException.class,()->f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-capture-outside","fictional-capture-outside",null),k->null,a->capture(null,null)));assertThrows(RuntimeException.class,()->capture(id,null));assertThrows(RuntimeException.class,()->capture(null,1L));assertThrows(RuntimeException.class,()->baseline.capture(scope,-1,null,null));var source=mock(javax.sql.DataSource.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);var intents=mock(JdbcLatestReportIntent.class);var originals=mock(ReportPreparedInputService.class);var contents=mock(ReportSupplementContentBaselineService.class);new ReportSupplementBaselineService(source,tx,intents,originals,contents);verifyNoInteractions(source,tx,intents,originals,contents);}
}
